---OrderInfoUpdate
---弹出页面现面后的逻辑处理
function CoffeeTakeoutTrackListDialog:OrderInfoUpdate()
    self:FreshUI()
end


function CoffeeTakeoutTrackListDialog:Awake()
    self.handler = Events.AddListener(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED, Bind(self, self.OrderInfoUpdate))
    SetButtonAction(self.FontStyleButton.gameObject, function()
        ----领取全部的按钮
        local hasFinished = 0
        ---@type MaidCoffeePlayerComponent
        local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
        local finishTeams = {}
        for _, teamId in pairs(self.teamIds) do
            local status = maidCoffeePlayerComponent:GetTakeoutTeamStatus(teamId)
            if status == MaidCoffeeConstants.TakeOutStatus.FINISHED then
                ----存在已完成的编队订单
                hasFinished = 1
                table.insert(finishTeams, teamId)
            end
        end
        if hasFinished == 0 then
            GameUtils.Toast(localize('当前没有已成的订单奖励可领取'))
        else
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutDrawAll, {}, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    ---成功了
                    local rdata = checkTable(response.data)
                    local rewards = checkTable(rdata.rewards)
                    ---@type CardComponent
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    ---更新已领取编队的卡牌状态
                    for _, teamId in pairs(finishTeams) do
                        local v = maidCoffeePlayerComponent:GetCardsByTeamId(teamId)
                        for _, id in pairs(v) do
                            cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                        end
                    end
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rewards)
                        ---关闭当前的页面
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = rewards }
                                }
                        )
                    end
                    ---重新请求一次，刷新定单
                    Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { isNewOrder = 1 })
                end
            end)
        end
    end)

  --[[  SetButtonAction(self.ClickClose.gameObject, function()
        --KTool.SetActive(self.DetailPopup.gameObject, false)
    end)]]
end

