    if index < 0 then
        return
    end
    local position = index + 1
    local cell = gridView:NewListViewItem(PrefabName)
    local teamId = self.teamIds[position]
    -----@type CoffeeTakeoutTrackListCellNode
    local env = CfUtils.GetLuaScr(cell.gameObject, ListCellNodePath)
    if env then
        env:FreshUI(teamId) --, Bind(self, self.OnProgressTakeOrder))
    end
    return cell
end

