function CoffeeTakeoutTrackListDialog:OnButtonAction(data, canOrder)
    local status = checkNumber(data.status)
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    if status == MaidCoffeeConstants.TakeOutStatus.PROGRESSING then
        ---@type GoodsVo
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.CoffeeTakeoutTicket)
        print('---->>', table.dump(vo, false, 3))
        local ticket = 1
        local remainTime = checkNumber(data.remainTime)
        local fixTime = 0
        if vo.effectType == Constants.GoodsEffectType.EffectShortTime then
            ---缩短时间
            if remainTime > 0 then
                ticket = math.ceil(remainTime / checkNumber(vo.effectNum))
            end
            fixTime = checkNumber(vo.effectNum)
        end
        local havNo = GoodsUtils.GetThingNo(vo.id)
        local text = string.format_size_tag(string.format_color_tag(second_toHHMMSS(data.remainTime), '#d7184a'), 42)
        GameUtils.SecondConfirm(localize('是否使用_num_个_name_立即完成订单', { _num_ = ticket, _name_ = vo.name }), function()
            if havNo < ticket then
                GameUtils.Toast(localize("_name_不足, 不能立即完成", { _name_ = vo.name }))
                return
            end
            GameUtils.Request(Interfaces.MaidCoffeeTakeoutDraw, {
                type = 2, orderId = data.id
            }, function(request, response)
                if checkNumber(response.errCode) == 0 then
                    --KTool.SetActive(self.DetailPopup.gameObject, false)
                    ---成功了
                    local rdata = checkTable(response.data)
                    local rewards = checkTable(rdata.rewards)
                    GoodsUtils.DrawRewards({ { goodsId = vo.id, num = -ticket } })
                    ---@type CardComponent
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    local v = maidCoffeePlayerComponent:GetCardsByTeamId(data.teamId)
                    for _, id in pairs(v) do
                        cardComponent:UpdateCardDojo(id, { cafeStatus = MaidCoffeeConstants.CafeStatus.Non })
                    end
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rdata.rewards)
                        ---关闭当前的页面
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = rdata.rewards }
                                }
                        )
                    end
                    ---重新请求一次，刷新定单
                    Events.Broadcast(Constants.EventNames.EVENT_TAKEOUT_POPUP_FINISHED, { data = data, isNewOrder = 1 })
                end
            end)
        end, function()

        end, localize('正在配送: _time_', { _time_ = text }), 4, { { goodsId = Constants.Currency.CoffeeTakeoutTicket, num = ticket } }, false, localize('每张外卖券可缩短_time_', { _time_ = CS.Engine.Tools.TimeUtils.HumanizeTimeString(fixTime) }), nil, checkNumber(data.id), UIModule.RootCanvas.transform)
    end
end

function CoffeeTakeoutTrackListDialog:FreshUI()
    ---@type MaidCoffeePlayerComponent
    local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
    local teams = maidCoffeePlayerComponent:GetAllTeam()
    local teamIds = table.keys(teams)
    table.sort(teamIds, function(a, b)
        local aKey, bKey = checkNumber(a), checkNumber(b) ---初始为teamId
        ---@type MaidCoffeeClerkSettingVo
        local voA = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(a)
        local voB = MaidCoffeeUtils.GetMaidCoffeeClerkSettingVo(b)
        if checkNumber(voA.vip) == 1 then
            aKey = aKey - 10
        end
        if checkNumber(voB.vip) == 1 then
            bKey = bKey - 10
        end
        local aStatus = maidCoffeePlayerComponent:GetTakeoutTeamStatus(a)
        local bStatus = maidCoffeePlayerComponent:GetTakeoutTeamStatus(b)
        if aStatus ~= MaidCoffeeConstants.TakeOutStatus.LOCKED then
            aStatus = -aStatus
        end
        if bStatus ~= MaidCoffeeConstants.TakeOutStatus.LOCKED then
            bStatus = -bStatus
        end
        aKey = aKey + aStatus
        bKey = bKey + bStatus
        return aKey < bKey
    end)
    self.teamIds = teamIds
    self:RefreshScrollView()
end

function CoffeeTakeoutTrackListDialog:RefreshScrollView()
    if self.ScrollView.IsListViewInit then
        GameUtils.ReloadData(self.ScrollView, 0)
        GameUtils.ReloadData(self.ScrollView, #self.teamIds)
    else
        self.ScrollView:InitGridView(#self.teamIds, Bind(self, self.OnGetItemByIndex))
    end
end


function CoffeeTakeoutTrackListDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshUI()
    end))
    return coWait
end

function CoffeeTakeoutTrackListDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if self.handler then
            Events.RemoveListener(Constants.EventNames.EVENT_TAKEOUT_DATA_CHANGED, self.handler)
        end
        self.handler = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CoffeeTakeoutTrackListDialog